import React, { useState } from "react";
import { Link, NavLink, Outlet, useNavigate } from "react-router-dom";
import {
  BarChart3,
  Box,
  LayoutDashboard,
  LineChart,
  LogOut,
  Menu,
  Package,
  PlusCircle,
  Settings,
  ShoppingCart,
  Star,
  X
} from "lucide-react";
import { useAuth } from "./AuthContext";
import { useTheme } from "./ThemeContext";
import { VENDOR_KPIS, VENDOR_ORDERS, VENDOR_PRODUCT_ROWS } from "./vendorMock";
import { h, f } from "./h";
import { Badge, Button, Field, GlassCard, GlassPanel, LogoMark, RefImage, SelectInput, TextArea, TextInput, ThemeToggleButton } from "./ui";

function NavItem({ to, icon: Icon, children, badge }) {
  return h(NavLink, {
    to,
    className: ({ isActive }) =>
      `flex items-center justify-between gap-2 rounded-2xl px-3 py-2.5 text-sm font-medium transition sm:px-4 sm:text-base ${
        isActive
          ? "bg-gradient-to-r from-sky-600/90 to-blue-700/90 text-white shadow-lg shadow-sky-900/30"
          : "text-slate-700 hover:bg-white/40 dark:text-slate-200 dark:hover:bg-white/10"
      }`,
    children: ({ isActive }) =>
      h(f, null, [
        h("span", { className: "flex items-center gap-2" }, [
          h(Icon, { className: `h-4 w-4 sm:h-5 sm:w-5 ${isActive ? "text-white" : ""}` }),
          children
        ]),
        badge != null &&
          h(
            "span",
            {
              className: `rounded-full px-2 py-0.5 text-[10px] font-bold ${
                isActive ? "bg-white/20 text-white" : "bg-amber-400/20 text-amber-800 dark:text-amber-200"
              }`
            },
            String(badge)
          )
      ])
  });
}

export function VendorShell() {
  const { dark, toggle } = useTheme();
  const { user, logout } = useAuth();
  const nav = useNavigate();
  const [open, setOpen] = useState(false);

  const onLogout = async () => {
    await logout();
    nav("/login", { replace: true });
  };

  const sidebar = h(
    "aside",
    {
      className: `fixed inset-y-0 left-0 z-40 w-72 max-w-[85vw] border-r border-white/10 bg-white/35 p-4 shadow-2xl backdrop-blur-2xl transition-transform dark:bg-night-900/50 lg:static lg:translate-x-0 ${
        open ? "translate-x-0" : "-translate-x-full lg:translate-x-0"
      }`
    },
    [
      h("div", { className: "mb-6 flex items-center justify-between lg:hidden" }, [
        h("span", { className: "font-display text-lg font-bold text-slate-900 dark:text-white" }, "Menu"),
        h(
          "button",
          {
            type: "button",
            className: "tap-target rounded-xl p-2 hover:bg-white/10",
            onClick: () => setOpen(false)
          },
          h(X, { className: "h-5 w-5" })
        )
      ]),
      h("div", { className: "mb-6 text-[10px] font-bold uppercase tracking-widest text-slate-500 dark:text-slate-400" }, "Main"),
      h("nav", { className: "space-y-1" }, [
        h(NavItem, { to: "/vendor/dashboard", icon: LayoutDashboard }, "Dashboard"),
        h(NavItem, { to: "/vendor/products", icon: Box }, "My products"),
        h(NavItem, { to: "/vendor/products/new", icon: PlusCircle }, "Add product"),
        h(NavItem, { to: "/vendor/orders", icon: ShoppingCart, badge: 4 }, "Orders")
      ]),
      h("div", { className: "mb-2 mt-6 text-[10px] font-bold uppercase tracking-widest text-slate-500 dark:text-slate-400" }, "Insights"),
      h("nav", { className: "space-y-1" }, [
        h(NavItem, { to: "/vendor/analytics", icon: LineChart }, "Analytics"),
        h(NavItem, { to: "/vendor/reviews", icon: Star, badge: 2 }, "Reviews")
      ]),
      h("div", { className: "mb-2 mt-6 text-[10px] font-bold uppercase tracking-widest text-slate-500 dark:text-slate-400" }, "Settings"),
      h("nav", { className: "space-y-1" }, [
        h(NavItem, { to: "/vendor/settings", icon: Settings }, "Store settings"),
        h(
          "button",
          {
            type: "button",
            onClick: onLogout,
            className:
              "flex w-full items-center gap-2 rounded-2xl px-3 py-2.5 text-left text-sm font-medium text-rose-400 hover:bg-rose-500/10 sm:px-4 sm:text-base"
          },
          [h(LogOut, { className: "h-4 w-4 sm:h-5 sm:w-5" }), "Logout"]
        )
      ]),
      h(
        GlassCard,
        { className: "mt-6 !border-sky-500/20 !bg-gradient-to-br !from-sky-900/80 !to-night-950 !p-4" },
        [
          h("p", { className: "text-xs font-bold uppercase tracking-wide text-sky-200" }, "Pro plan"),
          h("p", { className: "mt-1 text-xs text-white/80" }, "Unlimited listings • Analytics • Priority support")
        ]
      )
    ]
  );

  return h("div", { className: "min-h-screen bg-slate-100 dark:bg-night-950 dark:bg-mesh-dark" }, [
    open &&
      h("button", {
        type: "button",
        className: "fixed inset-0 z-30 bg-slate-950/50 backdrop-blur-sm lg:hidden",
        onClick: () => setOpen(false),
        "aria-label": "Close menu"
      }),
    h("div", { className: "flex min-h-screen" }, [
      sidebar,
      h("div", { className: "flex min-h-screen flex-1 flex-col" }, [
        h(
          "header",
          {
            className:
              "sticky top-0 z-20 border-b border-white/10 bg-white/30 px-4 py-3 backdrop-blur-xl dark:bg-night-900/40 sm:px-6"
          },
          h("div", { className: "mx-auto flex max-w-7xl items-center justify-between gap-3" }, [
            h(
              "button",
              {
                type: "button",
                className: "tap-target rounded-2xl border border-white/15 p-2 lg:hidden",
                onClick: () => setOpen(true)
              },
              h(Menu, { className: "h-5 w-5" })
            ),
            h("div", { className: "flex items-center gap-2" }, [
              h(LogoMark, { className: "h-9 w-9" }),
              h("span", { className: "font-display text-lg font-bold text-slate-900 dark:text-white" }, "BrewMart"),
              h(
                "span",
                { className: "hidden rounded-full bg-amber-400/20 px-2 py-0.5 text-[10px] font-bold uppercase text-amber-900 dark:text-amber-200 sm:inline" },
                "Vendor"
              )
            ]),
            h(
              "nav",
              { className: "hidden flex-1 justify-center gap-1 md:flex" },
              [
                ["Dashboard", "/vendor/dashboard"],
                ["Products", "/vendor/products"],
                ["Orders", "/vendor/orders"],
                ["Analytics", "/vendor/analytics"],
                ["Profile", "/vendor/profile"]
              ].map(([label, path]) =>
                h(NavLink, {
                  key: path,
                  to: path,
                  className: ({ isActive }) =>
                    `rounded-full px-3 py-2 text-sm font-medium ${
                      isActive
                        ? "bg-sky-500/15 text-sky-800 dark:text-sky-200"
                        : "text-slate-600 hover:bg-white/40 dark:text-slate-300 dark:hover:bg-white/10"
                    }`
                }, label)
              )
            ),
            h("div", { className: "flex items-center gap-2" }, [
              h(ThemeToggleButton, { dark, onToggle: toggle }),
              h("div", { className: "hidden items-center gap-2 rounded-2xl border border-white/10 bg-white/20 px-2 py-1 sm:flex dark:bg-white/5" }, [
                h(
                  "span",
                  {
                    className: "flex h-8 w-8 items-center justify-center rounded-full bg-sky-600 text-sm font-bold text-white"
                  },
                  (user?.email?.[0] || "K").toUpperCase()
                ),
                h("span", { className: "max-w-[120px] truncate text-xs font-medium text-slate-800 dark:text-slate-100" }, user?.email || "Kwame's store")
              ]),
              h(
                Link,
                { to: "/shop" },
                h(Button, { variant: "primary", className: "!min-h-[40px] !rounded-full !px-4 !text-sm" }, "Buyer view")
              )
            ])
          ])
        ),
        h("main", { className: "mx-auto w-full max-w-7xl flex-1 px-4 py-6 sm:px-6" }, h(Outlet))
      ])
    ])
  ]);
}

function KpiIcon({ name }) {
  const map = {
    wallet: Package,
    package: Box,
    "shopping-bag": ShoppingCart,
    star: Star
  };
  const Icon = map[name] || BarChart3;
  return h(
    "div",
    {
      className:
        "flex h-11 w-11 items-center justify-center rounded-2xl bg-sky-500/15 text-sky-600 dark:text-sky-300"
    },
    h(Icon, { className: "h-5 w-5" })
  );
}

export function VendorDashboardPage() {
  return h(f, null, [
    h("div", { className: "mb-6 flex flex-wrap items-center justify-between gap-3" }, [
      h("div", {}, [
        h("h1", { className: "font-display text-2xl font-bold text-slate-900 dark:text-white" }, "Good morning, Kwame ☀️"),
        h("p", { className: "text-sm text-slate-600 dark:text-slate-400" }, "Here's how your store is performing today.")
      ]),
      h(Link, { to: "/vendor/products/new" }, h(Button, { className: "!rounded-full" }, [h(PlusCircle, { className: "h-4 w-4" }), "Add product"]))
    ]),
    h("div", { className: "mb-8 grid grid-cols-1 gap-4 sm:grid-cols-2 xl:grid-cols-4" }, [
      VENDOR_KPIS.map((k) =>
        h(GlassCard, { key: k.label }, [
          h("div", { className: "flex items-start justify-between gap-3" }, [
            h("div", {}, [
              h("p", { className: "text-xs font-semibold uppercase tracking-wide text-slate-500 dark:text-slate-400" }, k.label),
              h("p", { className: "mt-2 text-2xl font-bold text-slate-900 dark:text-white" }, k.value),
              h("p", { className: "mt-1 text-xs font-medium text-emerald-500 dark:text-emerald-400" }, k.delta)
            ]),
            h(KpiIcon, { name: k.icon })
          ])
        ])
      )
    ]),
    h("div", { className: "grid grid-cols-1 gap-6 lg:grid-cols-3" }, [
      h(GlassPanel, { className: "lg:col-span-2" }, [
        h("div", { className: "mb-4 flex items-center justify-between" }, [
          h("h2", { className: "text-lg font-semibold text-slate-900 dark:text-white" }, "Revenue this week"),
          h(
            SelectInput,
            { defaultValue: "week" },
            [h("option", { value: "week" }, "This week"), h("option", { value: "month" }, "This month")]
          )
        ]),
        h(
          "div",
          { className: "flex h-48 items-end justify-between gap-2 rounded-2xl border border-white/10 bg-night-900/40 p-4" },
          [
            ["Mon", 40],
            ["Tue", 55],
            ["Wed", 48],
            ["Thu", 70],
            ["Fri", 62],
            ["Sat", 80],
            ["Sun", 58]
          ].map(([d, hgt]) =>
            h(
              "div",
              { key: d, className: "flex flex-1 flex-col items-center gap-2" },
              [
                h("div", {
                  className: "w-full max-w-[2.5rem] rounded-t-xl bg-gradient-to-t from-sky-600 to-sky-400",
                  style: { height: `${hgt}%` }
                }),
                h("span", { className: "text-[10px] text-slate-500 dark:text-slate-400" }, d)
              ]
            )
          )
        )
      ]),
      h(GlassPanel, {}, [
        h("h2", { className: "text-lg font-semibold text-slate-900 dark:text-white" }, "Sales by category"),
        h("div", { className: "mt-4 flex flex-col items-center gap-4" }, [
          h("div", { className: "relative h-36 w-36 rounded-full border-[10px] border-sky-500/40 border-t-emerald-400/80 border-r-amber-400/70" }),
          h("ul", { className: "w-full space-y-2 text-sm" }, [
            h("li", { className: "flex items-center justify-between" }, [
              h("span", { className: "flex items-center gap-2 text-slate-600 dark:text-slate-300" }, [
                h("span", { className: "h-2 w-2 rounded-full bg-sky-500" }),
                "Coffee beans"
              ]),
              h("span", { className: "font-semibold text-slate-900 dark:text-white" }, "65%")
            ]),
            h("li", { className: "flex items-center justify-between" }, [
              h("span", { className: "flex items-center gap-2 text-slate-600 dark:text-slate-300" }, [
                h("span", { className: "h-2 w-2 rounded-full bg-emerald-400" }),
                "Gear"
              ]),
              h("span", { className: "font-semibold text-slate-900 dark:text-white" }, "20%")
            ]),
            h("li", { className: "flex items-center justify-between" }, [
              h("span", { className: "flex items-center gap-2 text-slate-600 dark:text-slate-300" }, [
                h("span", { className: "h-2 w-2 rounded-full bg-amber-400" }),
                "Other"
              ]),
              h("span", { className: "font-semibold text-slate-900 dark:text-white" }, "15%")
            ])
          ])
        ])
      ])
    ]),
    h("div", { className: "mt-8" }, [
      h("div", { className: "mb-3 flex items-center justify-between" }, [
        h("h2", { className: "text-lg font-semibold text-slate-900 dark:text-white" }, "Recent orders"),
        h("button", { type: "button", className: "text-sm font-semibold text-sky-600 hover:underline dark:text-sky-300" }, "View all →")
      ]),
      h(GlassCard, { className: "!p-0 overflow-hidden" }, h("div", { className: "divide-y divide-white/10" }, VENDOR_ORDERS.slice(0, 3).map((o) => h("div", { key: o.id, className: "flex flex-wrap items-center justify-between gap-2 px-4 py-3" }, [h("span", { className: "font-mono text-sm text-slate-600 dark:text-slate-300" }, o.id), h("span", { className: "text-sm text-slate-900 dark:text-white" }, o.customer), h(Badge, { tone: "success" }, o.status)]))))
    ])
  ]);
}

function productStatusTone(s) {
  if (s === "Active") return "success";
  if (s === "Out of Stock") return "danger";
  return "warn";
}

export function VendorProductsPage() {
  return h(f, null, [
    h("div", { className: "mb-6 flex flex-wrap items-center justify-between gap-3" }, [
      h("h1", { className: "flex items-center gap-2 font-display text-2xl font-bold text-slate-900 dark:text-white" }, [
        h(Box, { className: "h-7 w-7 text-sky-400" }),
        "My products"
      ]),
      h("div", { className: "flex flex-1 flex-wrap items-center gap-2 sm:flex-initial" }, [
        h(TextInput, { placeholder: "Search products…", className: "!min-w-[200px] flex-1 sm:max-w-xs" }),
        h(Link, { to: "/vendor/products/new" }, h(Button, { className: "!rounded-full" }, [h(PlusCircle, { className: "h-4 w-4" }), "Add product"]))
      ])
    ]),
    h(GlassCard, { className: "!overflow-x-auto !p-0" }, h("table", { className: "w-full min-w-[640px] text-left text-sm" }, [
      h("thead", { className: "border-b border-white/10 bg-white/20 text-xs uppercase text-slate-500 dark:bg-white/5 dark:text-slate-400" }, h("tr", null, [
        h("th", { className: "px-4 py-3" }, "Product"),
        h("th", { className: "px-4 py-3" }, "Category"),
        h("th", { className: "px-4 py-3" }, "Price"),
        h("th", { className: "px-4 py-3" }, "Stock"),
        h("th", { className: "px-4 py-3" }, "Sales"),
        h("th", { className: "px-4 py-3" }, "Status"),
        h("th", { className: "px-4 py-3" }, "Actions")
      ])),
      h(
        "tbody",
        { className: "divide-y divide-white/10" },
        VENDOR_PRODUCT_ROWS.map((row, i) =>
          h("tr", { key: row.name, className: "hover:bg-white/10" }, [
            h("td", { className: "px-4 py-3" }, h("div", { className: "flex items-center gap-3" }, [
              h(RefImage, { n: i + 1, alt: row.name, className: "h-10 w-10 rounded-lg object-cover" }),
              h("span", { className: "font-medium text-slate-900 dark:text-white" }, row.name)
            ])),
            h("td", { className: "px-4 py-3 text-slate-600 dark:text-slate-300" }, row.category),
            h("td", { className: "px-4 py-3 font-semibold text-slate-900 dark:text-white" }, `$${row.price.toFixed(2)}`),
            h("td", { className: "px-4 py-3" }, row.stock),
            h("td", { className: "px-4 py-3" }, row.sales),
            h("td", { className: "px-4 py-3" }, h(Badge, { tone: productStatusTone(row.status) }, row.status)),
            h("td", { className: "px-4 py-3" }, h("div", { className: "flex gap-2" }, [
              h(Button, { variant: "ghost", className: "!min-h-[36px] !px-3 !py-2 !text-xs" }, "Edit"),
              h(Button, { variant: "danger", className: "!min-h-[36px] !px-3 !py-2 !text-xs" }, "Delete")
            ]))
          ])
        )
      )
    ]))
  ]);
}

export function VendorAddProductPage() {
  return h(f, null, [
    h("div", { className: "mb-6 flex flex-wrap items-center justify-between gap-3" }, [
      h("h1", { className: "font-display text-2xl font-bold text-slate-900 dark:text-white" }, "Add new product"),
      h(Link, { to: "/vendor/products" }, h(Button, { variant: "ghost", className: "!rounded-full" }, "← Back to products"))
    ]),
    h("div", { className: "grid grid-cols-1 gap-6 lg:grid-cols-3" }, [
      h("div", { className: "space-y-6 lg:col-span-2" }, [
        h(GlassPanel, {}, [
          h("h2", { className: "mb-4 font-semibold text-slate-900 dark:text-white" }, "Product details"),
          h("div", { className: "space-y-4" }, [
            h(Field, { label: "Product name" }, h(TextInput, { placeholder: "e.g. Ethiopian Yirgacheffe beans" })),
            h(Field, { label: "Description" }, h(TextArea, { placeholder: "Tell buyers what makes this special…" })),
            h("div", { className: "grid grid-cols-1 gap-4 sm:grid-cols-2" }, [
              h(Field, { label: "Price ($)" }, h(TextInput, { type: "number", placeholder: "18.99" })),
              h(Field, { label: "Compare at ($)" }, h(TextInput, { type: "number", placeholder: "24.99" }))
            ]),
            h("div", { className: "grid grid-cols-1 gap-4 sm:grid-cols-2" }, [
              h(Field, { label: "Category" }, h(SelectInput, {}, [h("option", null, "Coffee beans"), h("option", null, "Gear"), h("option", null, "Mugs")])),
              h(Field, { label: "Stock quantity" }, h(TextInput, { type: "number", placeholder: "42" }))
            ])
          ])
        ]),
        h(GlassPanel, {}, [
          h("h2", { className: "mb-2 font-semibold text-slate-900 dark:text-white" }, "Product images"),
          h("div", { className: "flex min-h-[140px] items-center justify-center rounded-2xl border-2 border-dashed border-sky-400/40 bg-sky-500/5 text-sm text-slate-500 dark:text-slate-400" }, "Drop images here or click to upload (UI only)")
        ])
      ]),
      h("div", { className: "space-y-6" }, [
        h(GlassPanel, {}, [
          h("h2", { className: "mb-4 font-semibold text-slate-900 dark:text-white" }, "Publish"),
          h(Field, { label: "Status" }, h(SelectInput, {}, [h("option", null, "Active"), h("option", null, "Draft")])),
          h(Button, { className: "mt-4 w-full" }, "Publish product"),
          h(Button, { variant: "ghost", className: "mt-2 w-full" }, "Save as draft")
        ]),
        h(GlassPanel, {}, [
          h("h2", { className: "mb-4 font-semibold text-slate-900 dark:text-white" }, "Shipping"),
          h(Field, { label: "Weight (kg)" }, h(TextInput, { type: "number", placeholder: "0.5" })),
          h(Field, { label: "Shipping zone" }, h(SelectInput, {}, [h("option", null, "Nationwide"), h("option", null, "Accra only")]))
        ])
      ])
    ])
  ]);
}

export function VendorOrdersPage() {
  const payTone = (p) => (p === "Card" ? "info" : "neutral");
  const statusTone = (s) => {
    if (s === "Delivered") return "success";
    if (s === "In Transit") return "warn";
    if (s === "Cancelled") return "danger";
    return "neutral";
  };
  return h(f, null, [
    h("div", { className: "mb-6 flex flex-wrap items-center justify-between gap-3" }, [
      h("h1", { className: "flex items-center gap-2 font-display text-2xl font-bold text-slate-900 dark:text-white" }, [
        h(ShoppingCart, { className: "h-7 w-7 text-sky-400" }),
        "Order management"
      ]),
      h("div", { className: "flex flex-wrap gap-2" }, [
        h(
          SelectInput,
          { defaultValue: "all", className: "!w-auto" },
          [h("option", { value: "all" }, "All status"), h("option", null, "Processing")]
        ),
        h(Button, { variant: "ghost", className: "!rounded-full" }, "Export")
      ])
    ]),
    h(GlassCard, { className: "!overflow-x-auto !p-0" }, h("table", { className: "w-full min-w-[900px] text-left text-sm" }, [
      h("thead", { className: "border-b border-white/10 bg-white/20 text-xs uppercase dark:bg-white/5" }, h("tr", null, ["Order ID", "Customer", "Product", "Qty", "Amount", "Payment", "Status", "Action"].map((c) => h("th", { key: c, className: "px-3 py-3" }, c)))),
      h(
        "tbody",
        { className: "divide-y divide-white/10" },
        VENDOR_ORDERS.map((o) =>
          h("tr", { key: o.id, className: "hover:bg-white/5" }, [
            h("td", { className: "px-3 py-3 font-mono text-xs" }, o.id),
            h("td", { className: "px-3 py-3" }, o.customer),
            h("td", { className: "px-3 py-3" }, o.product),
            h("td", { className: "px-3 py-3" }, o.qty),
            h("td", { className: "px-3 py-3 font-semibold" }, `$${o.amount.toFixed(2)}`),
            h("td", { className: "px-3 py-3" }, h(Badge, { tone: payTone(o.payment) }, o.payment)),
            h("td", { className: "px-3 py-3" }, h(Badge, { tone: statusTone(o.status) }, o.status)),
            h("td", { className: "px-3 py-3" }, h(Button, { variant: "ghost", className: "!min-h-[36px] !px-3 !py-1 !text-xs" }, "View"))
          ])
        )
      )
    ]))
  ]);
}

export function VendorAnalyticsPage() {
  return h(f, null, [
    h("div", { className: "mb-6 flex flex-wrap items-center justify-between gap-3" }, [
      h("h1", { className: "flex items-center gap-2 font-display text-2xl font-bold text-slate-900 dark:text-white" }, [
        h(LineChart, { className: "h-7 w-7 text-sky-400" }),
        "Analytics overview"
      ]),
      h(SelectInput, { defaultValue: "7", className: "!w-auto" }, [h("option", { value: "7" }, "Last 7 days"), h("option", null, "Last 30 days")])
    ]),
    h(
      "div",
      { className: "mb-8 grid grid-cols-1 gap-4 sm:grid-cols-2 xl:grid-cols-4" },
      [
        { label: "Total revenue", value: "$3,842", d: "↑ 12%" },
        { label: "Product views", value: "12.4K", d: "↑ 18%" },
        { label: "Conversion", value: "8.7%", d: "↑ 2.1%" },
        { label: "Repeat buyers", value: "42%", d: "↑ 5%" }
      ].map((x) =>
